// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { AspectRatio } from "@/registry/erbium/ui/aspect-ratio";

import PlaygroundExample, { defaultProps as PlaygroundDefaults } from "./variants/playground";



import OverviewExample from "./variants/overview";



import SquareExample from "./variants/square";



import PortraitExample from "./variants/portrait";



const meta = {
  component: AspectRatio,
  parameters: {
    docs: {
      description: {
        component: "Keeps content at a fixed aspect ratio.\n\n**Import:** `@/registry/erbium/ui/aspect-ratio`\n\n## Usage\n\n```tsx\nimport { AspectRatio } from \"@/registry/erbium/ui/aspect-ratio\";\n```\n\n```tsx\n<AspectRatio ratio={16 / 9}>\n  <Image src=\"...\" alt=\"Image\" className=\"rounded-md object-cover\" />\n</AspectRatio>\n```",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof AspectRatio>;

export default { ...meta, title: "Components/Aspect Ratio",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<typeof AspectRatio> = {
  argTypes: { ratio: { control: { max: 4, min: 0.25, step: 0.25, type: "number" } } },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { AspectRatio } from \"@/registry/erbium/ui/aspect-ratio\";\nimport type * as React from \"react\";\n\nexport const defaultProps = {\n  className: \"\",\n  ratio: 16 / 9,\n} satisfies React.ComponentProps<typeof AspectRatio>;\n\nexport default function AspectRatioPlaygroundExample(\n  args: React.ComponentProps<typeof AspectRatio> = defaultProps,\n) {\n  return (\n    <AspectRatio\n      {...args}\n      className={`w-80 overflow-hidden rounded-md bg-muted ${args.className ?? \"\"}`}\n    >\n      <div className=\"flex size-full items-center justify-center\">Content at {args.ratio}:1</div>\n    </AspectRatio>\n  );\n}\n" },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { AspectRatio } from \"@/registry/erbium/ui/aspect-ratio\";\n\nexport default function AspectRatioExample() {\n  return (\n    <div className=\"w-80\">\n      <AspectRatio ratio={16 / 9}>\n        <div className=\"flex size-full items-center justify-center rounded-lg bg-muted\">\n          16:9 media area\n        </div>\n      </AspectRatio>\n    </div>\n  );\n}\n" },
    },
  },
  render: OverviewExample,
};

export const Square: Story = {
  parameters: {
    docs: {
      description: { story: "A square aspect ratio component using the `ratio={1 / 1}` prop. This is useful for displaying images in a square format." },
      source: { code: "import { AspectRatio } from \"@/registry/erbium/ui/aspect-ratio\";\n\nexport default function AspectRatioSquareExample() {\n  return (\n    <div className=\"w-60\">\n      <AspectRatio ratio={1}>\n        <div className=\"flex size-full items-center justify-center rounded-lg bg-muted\">\n          Square 1:1\n        </div>\n      </AspectRatio>\n    </div>\n  );\n}\n" },
    },
  },
  render: SquareExample,
};

export const Portrait: Story = {
  parameters: {
    docs: {
      description: { story: "A portrait aspect ratio component using the `ratio={9 / 16}` prop. This is useful for displaying images in a portrait format." },
      source: { code: "import { AspectRatio } from \"@/registry/erbium/ui/aspect-ratio\";\n\nexport default function AspectRatioPortraitExample() {\n  return (\n    <div className=\"w-40\">\n      <AspectRatio ratio={9 / 16}>\n        <div className=\"flex size-full items-center justify-center rounded-lg bg-muted\">\n          Portrait 9:16\n        </div>\n      </AspectRatio>\n    </div>\n  );\n}\n" },
    },
  },
  render: PortraitExample,
};

import { AspectRatio } from "@/registry/erbium/ui/aspect-ratio";

export default function AspectRatioExample() {
  return (
    <div className="w-80">
      <AspectRatio ratio={16 / 9}>
        <div className="flex size-full items-center justify-center rounded-lg bg-muted">
          16:9 media area
        </div>
      </AspectRatio>
    </div>
  );
}

import AspectRatioExample from "../examples/aspect-ratio-demo";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <AspectRatioExample />
  </div>
);

export default Example;

import { AspectRatio } from "@/registry/erbium/ui/aspect-ratio";
import type * as React from "react";

export const defaultProps = {
  className: "",
  ratio: 16 / 9,
} satisfies React.ComponentProps<typeof AspectRatio>;

export default function AspectRatioPlaygroundExample(
  args: React.ComponentProps<typeof AspectRatio> = defaultProps,
) {
  return (
    <AspectRatio
      {...args}
      className={`w-80 overflow-hidden rounded-md bg-muted ${args.className ?? ""}`}
    >
      <div className="flex size-full items-center justify-center">Content at {args.ratio}:1</div>
    </AspectRatio>
  );
}

import { AspectRatio } from "@/registry/erbium/ui/aspect-ratio";

export default function AspectRatioPortraitExample() {
  return (
    <div className="w-40">
      <AspectRatio ratio={9 / 16}>
        <div className="flex size-full items-center justify-center rounded-lg bg-muted">
          Portrait 9:16
        </div>
      </AspectRatio>
    </div>
  );
}

import { AspectRatio } from "@/registry/erbium/ui/aspect-ratio";

export default function AspectRatioSquareExample() {
  return (
    <div className="w-60">
      <AspectRatio ratio={1}>
        <div className="flex size-full items-center justify-center rounded-lg bg-muted">
          Square 1:1
        </div>
      </AspectRatio>
    </div>
  );
}

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

/**
 * The box an example renders in. Inline it is capped to the reading width; with `fill` (a
 * full-screen slide) it takes the whole panel, so an example sized from its container (`w-full`,
 * `h-full` with a minimum) grows with it, while one with a natural size stays centred.
 */
export const ShowcaseSurface = ({
  children,
  fill = false,
}: {
  children?: ReactNode;
  fill?: boolean;
}) => (
  <div
    data-slot="component-preview"
    className={cn(
      "relative isolate mx-auto flex w-full min-w-0 items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center",
      fill ? "flex-1" : "min-h-64 max-w-3xl",
    )}
  >
    {children}
  </div>
);
